import{_ as e,o,c as a,a2 as s}from"./chunks/framework.DYPTBNgj.js";const m=JSON.parse('{"title":"Local Models Quickstart","description":"","frontmatter":{},"headers":[],"relativePath":"guide/local-models-quickstart.md","filePath":"guide/local-models-quickstart.md"}'),l={name:"guide/local-models-quickstart.md"};function n(d,t,i,r,h,c){return o(),a("div",null,[...t[0]||(t[0]=[s('<h1 id="local-models-quickstart" tabindex="-1">Local Models Quickstart <a class="header-anchor" href="#local-models-quickstart" aria-label="Permalink to &quot;Local Models Quickstart&quot;">​</a></h1><p>By the end of this page, an <strong>AI Prompt</strong> node in Aerini will answer a question using a model running on your own computer. The prompt and the reply never leave your machine, and there&#39;s no API key and no bill. It takes about 15 minutes, most of it waiting for a model to download.</p><p><strong>You&#39;ll need:</strong> the Aerini desktop app (see <a href="./../getting-started/installation">Installation</a>) and enough free disk space for a model. Models are multi-gigabyte downloads.</p><h2 id="what-this-is-in-one-minute" tabindex="-1">What this is, in one minute <a class="header-anchor" href="#what-this-is-in-one-minute" aria-label="Permalink to &quot;What this is, in one minute&quot;">​</a></h2><p>A <strong>local model</strong> is an AI model that runs on your hardware instead of in a company&#39;s cloud. <strong>Ollama</strong> is a free program that downloads these models and runs them. Aerini talks to Ollama over your own machine, the same way it would talk to OpenAI or Claude over the internet, so any workflow you can build with a hosted model works with a local one.</p><p>Two programs, two jobs:</p><table tabindex="0"><thead><tr><th>Program</th><th>Job</th></tr></thead><tbody><tr><td><strong>Ollama</strong></td><td>Downloads models, keeps them on disk, runs them.</td></tr><tr><td><strong>Aerini</strong></td><td>Sends the prompt to Ollama and uses the reply in your workflow.</td></tr></tbody></table><p>Ollama owns the models. You can download one with Ollama in a terminal (Step 2), or with the <strong>Pull model</strong> button on the node in the desktop app (Step 4). Aerini&#39;s <strong>Fetch Models</strong> button shows which ones you have installed.</p><h2 id="step-1-install-ollama" tabindex="-1">Step 1: Install Ollama <a class="header-anchor" href="#step-1-install-ollama" aria-label="Permalink to &quot;Step 1: Install Ollama&quot;">​</a></h2><p>Download the installer for your system from <a href="https://ollama.com/download" target="_blank" rel="noreferrer">ollama.com/download</a> and run it. On Linux, Ollama&#39;s own install script also works:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://ollama.com/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sh</span></span></code></pre></div><h2 id="step-2-download-a-model" tabindex="-1">Step 2: Download a model <a class="header-anchor" href="#step-2-download-a-model" aria-label="Permalink to &quot;Step 2: Download a model&quot;">​</a></h2><p>Open a terminal (PowerShell on Windows) and run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ollama</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> llama3.2</span></span></code></pre></div><p>This downloads the model once and stores it on disk. It can take a while on a slow connection. Ollama&#39;s own documentation says to pull a model before you use it.</p><p>Check that it&#39;s there:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ollama</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span></code></pre></div><p>You should see <code>llama3.2</code> in the list. Ollama is now running in the background on <code>http://localhost:11434</code>.</p><p>Prefer not to use a terminal? Skip the pull for now: once Step 4 points the node at Ollama, type the name in <strong>Model</strong> and click <strong>Pull model</strong> instead.</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p><code>llama3.2</code> is just a small, popular example. Any model Ollama can run works the same way in Aerini. Whatever you pull, you&#39;ll use its exact name in Step 4.</p></div><h2 id="step-3-build-a-three-node-workflow" tabindex="-1">Step 3: Build a three-node workflow <a class="header-anchor" href="#step-3-build-a-three-node-workflow" aria-label="Permalink to &quot;Step 3: Build a three-node workflow&quot;">​</a></h2><p>Open Aerini and start a blank canvas, as in <a href="./../getting-started/getting-started">Getting Started</a>. Add these three nodes and connect them in order:</p><ol><li><strong>Manual Trigger</strong> (under Triggers)</li><li><strong>AI Prompt</strong> (under AI)</li><li><strong>Output</strong> (under Utility)</li></ol><h2 id="step-4-point-ai-prompt-at-ollama" tabindex="-1">Step 4: Point AI Prompt at Ollama <a class="header-anchor" href="#step-4-point-ai-prompt-at-ollama" aria-label="Permalink to &quot;Step 4: Point AI Prompt at Ollama&quot;">​</a></h2><p>Double-click <strong>AI Prompt</strong> to open its settings, and set:</p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th><th>Why</th></tr></thead><tbody><tr><td><strong>Provider</strong></td><td><code>local</code></td><td><code>auto</code> also works, but picking <code>local</code> makes the <strong>Use Ollama defaults</strong> button appear.</td></tr><tr><td><strong>Base URL</strong></td><td>Click <strong>Use Ollama defaults</strong></td><td>It fills in <code>http://localhost:11434/v1</code>. The <code>http://</code> and the <code>/v1</code> both matter.</td></tr><tr><td><strong>Model</strong></td><td>Click <strong>Fetch Models</strong>, then pick <code>llama3.2</code></td><td>Fetch Models lists the models Ollama already has on disk. You can also type the name.</td></tr><tr><td><strong>Prompt</strong></td><td><code>Say hello in five words.</code></td><td>Anything will do for a first test.</td></tr><tr><td><strong>API Key</strong></td><td>leave empty</td><td>Ollama doesn&#39;t check for one.</td></tr></tbody></table><p><strong>Fetch Models</strong> asks your Ollama server what it has installed and shows the answer as a dropdown. It only lists; it never downloads anything. If the list comes back empty, you haven&#39;t pulled a model yet: go back to Step 2, or type <code>llama3.2</code> in <strong>Model</strong> and click <strong>Pull model</strong>, which appears under <strong>Fetch Models</strong> once Aerini sees Ollama. Closing the node&#39;s settings stops a download in progress.</p><h2 id="step-5-run-it" tabindex="-1">Step 5: Run it <a class="header-anchor" href="#step-5-run-it" aria-label="Permalink to &quot;Step 5: Run it&quot;">​</a></h2><p>Press <strong>Run</strong>. The first reply is slow, because Ollama has to load the model into memory. Replies after that are quicker. Ollama keeps a model loaded for about five minutes after its last use by default, so a pause longer than that means the next request pays the loading cost again.</p><p>Open <strong>Output</strong>&#39;s result and you should see what AI Prompt returned: the reply in <code>content</code>, plus the <code>model</code> and <code>provider</code> it used.</p><p>You&#39;ve now run a model on your own machine from a visual workflow.</p><h2 id="if-it-didn-t-work" tabindex="-1">If it didn&#39;t work <a class="header-anchor" href="#if-it-didn-t-work" aria-label="Permalink to &quot;If it didn&#39;t work&quot;">​</a></h2><table tabindex="0"><thead><tr><th>What you see</th><th>What to do</th></tr></thead><tbody><tr><td>A network error straight away</td><td>Ollama isn&#39;t running, or the port in Base URL is wrong. Start Ollama and check Base URL.</td></tr><tr><td><code>model is required when provider is &quot;local&quot;</code></td><td>Model is blank. Fetch Models and pick one, or type the name.</td></tr><tr><td>The reply is empty, or the node says it can&#39;t find the model</td><td>The Model name doesn&#39;t match an installed one. Run <code>ollama list</code> and copy the name exactly.</td></tr><tr><td><code>URL scheme &#39;localhost&#39; is not permitted</code></td><td><code>http://</code> is missing from the front of Base URL.</td></tr></tbody></table><p>More causes and fixes are in <a href="./local-models#if-it-s-not-working">Local Models, If it&#39;s not working</a>.</p><h2 id="where-next" tabindex="-1">Where next <a class="header-anchor" href="#where-next" aria-label="Permalink to &quot;Where next&quot;">​</a></h2><table tabindex="0"><thead><tr><th>You want to...</th><th>Go to</th></tr></thead><tbody><tr><td>Chat with this model from a window inside Aerini</td><td><a href="./chat-with-a-local-model">Chat with a Local Model</a></td></tr><tr><td>Save the Base URL and Model so you don&#39;t retype them</td><td><a href="./local-models#reusing-this-setup-with-a-saved-credential">Local Models, Reusing this setup</a></td></tr><tr><td>Reach Ollama on another machine on your network</td><td><a href="./local-models#reaching-a-model-server-on-your-lan-not-just-this-machine">Local Models, Reaching a model server on your LAN</a></td></tr><tr><td>Use a local model with the AI Agent node and tools</td><td><a href="./local-models#ai-agent">Local Models, AI Agent</a></td></tr><tr><td>Look up every field</td><td><a href="./nodes#ai-prompt">Nodes Reference, AI Prompt</a></td></tr></tbody></table><details class="details custom-block"><summary>For experienced users</summary><ul><li>The <code>local</code> provider is wire-identical to <code>openai</code>: Aerini posts to your Base URL plus <code>/chat/completions</code>. Ollama serves that under <code>/v1</code>.</li><li><code>auto</code> resolves to <code>local</code> for the literal hostname <code>localhost</code> and for loopback and private-network IPs, by inspecting the URL text, not DNS. A hostname that needs a lookup, such as <code>myollama.local</code>, falls back to <code>openai</code>, so set Provider to <code>local</code> there.</li><li><strong>Fetch Models</strong> calls your server&#39;s <code>/models</code> endpoint with the node&#39;s current Provider, Base URL and key. Ollama exposes <code>/v1/models</code> as part of its OpenAI compatibility.</li><li>The request goes through the <code>AllowLocal</code> SSRF policy, which permits loopback and private ranges for this field only. See <a href="./security#ssrf-protection">Security</a>.</li><li><strong>Context window.</strong> Current Ollama documentation says the default context window is 4096 tokens, and that older versions used 2048. A long chat history or a big attached file can silently exceed it. Raise it with <code>OLLAMA_CONTEXT_LENGTH</code>, for example <code>OLLAMA_CONTEXT_LENGTH=8192 ollama serve</code>.</li><li><strong>Timeout.</strong> The node waits up to 3600 seconds by default (range 10 to 86400). Raise <strong>Timeout (seconds)</strong> for slow hardware or big models.</li></ul></details>',37)])])}const u=e(l,[["render",n]]);export{m as __pageData,u as default};
